head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > M > getFrame]<br/>인덱스값 또는 Tabs ID 값을 사용하여 특정 Tab 페이지의 Frame 객체를 반환합니다.",
    "validation" : [
        "info(필수) 파라미터로 Frame 객체를 반환받으려는 Tab 페이지의 인덱스값을 설정합니다.",
        "Tab 페이지의 인덱스는 0 부터 시작합니다.",
        "반환값으로 파라미터에 해당하는 Tab 페이지의 Frame 객체를 반환합니다.",
        "파라미터를 생략하거나 잘못된 값 설정 시 undefined 를 반환합니다.",
        "Tabs 의 frameMode='wframePreload','pageFrame' 이면 Frame 의 생성 및 로딩이 완료된 상태여서 변경된 Frame 설정이 렌더링때 반영됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onchange"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    // $c.gcm.createLabel('label="활성화 되지 않은 Tab 페이지의 src 를 변경 후 해당 Tab 버튼을 클릭하여 이동 시 src 유지 되어야 함"', '', 'label1');

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + eList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content frameMode="wframePreload"  src="/sample/common_link/tabControl_link_1.xml" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content frameMode="pageFrame" src="/sample/common_link/tabControl_link_1.xml" style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content frameMode="wframePreload" src="/sample/common_link/tabControl_link_1.xml" style="height:160px" id="content3">';    
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.btn_getFrame_onclick = async function (e) {
    let info = par_info.getText();
    let tabFrame = null;

    if (info == "")
        tabFrame = target1.getFrame();
    else
        tabFrame = target1.getFrame(info);

    wf_body_bottom.getObj("scwin").setReturnValue("tabFrame : " + tabFrame);

    await tabFrame.setSrc("/sample/common_link/tabControl_link_2.xml");

    wf_body_bottom.getObj("scwin").setReturnValue("tabFrame.getSrc : " + tabFrame.getSrc());
}



scwin.target1_onchange = function (tabId, index, userId) {
    let tabFrame = target1.getFrame(index);

    wf_body_bottom.getObj("scwin").setReturnValue("tabFrame.getSrc : " + tabFrame.getSrc());
}
